/*!
 * Next.js - AeroDelay AI Premium Frontend
 * Reusable UI components - Card, Panel, Badge, Gauge, Skeleton, Divider
 *
 * Phase 5.3 fixes:
 *  - GlassPanel/SectionDivider accept `className` (pages passed it; the old
 *    component only knew `classNameExtra`, silently dropping all styling)
 *  - StatusBadge uses complete literal Tailwind class strings (dynamic
 *    `bg-${...}` interpolation is never generated by Tailwind)
 *  - RiskGauge uses a proper style object and camelCase SVG attributes
 *    (the old string `style` prop with `${...}` text was invalid JSX/CSS)
 *  - LoadingSkeleton uses animate-pulse instead of animate-bounce
 */

import type { CSSProperties, ReactNode } from "react";

/*
 * Glass Panel - Premium aviation visual design
 * - Selective use for depth without performance cost
 * - Glassmorphism with navy background and cyan accent
 */
export function GlassPanel({
  className = "",
  classNameExtra = "",
  children,
  minHeight,
}: {
  className?: string;
  classNameExtra?: string;
  children: ReactNode;
  minHeight?: string;
}) {
  // Tailwind cannot build `min-h-[${minHeight}]` dynamically, so apply it
  // as an inline style instead. Bare numbers are treated as pixels.
  let minHStyle: string | undefined;
  if (minHeight && minHeight !== "auto") {
    minHStyle = /^\d+$/.test(minHeight) ? `${minHeight}px` : minHeight;
  }

  return (
    <div
      className={`rounded-2xl p-6 md:p-8 bg-navy-950/50 backdrop-blur-sm border border-navy-800/50 ${className} ${classNameExtra}`}
      style={minHStyle ? { minHeight: minHStyle } : undefined}
    >
      {children}
    </div>
  );
}

/*
 * Flight Info Card - Compact flight information display
 * - Used in lists and summaries
 * - Shows key flight details at a glance
 */
export function FlightInfoCard({
  flight,
  showRisk = true,
  onSelect,
}: {
  flight: {
    id: string;
    flightNumber: string;
    origin: string;
    destination: string;
    status: string;
    scheduledDeparture: string;
    actualDeparture?: string;
    scheduledArrival?: string;
    actualArrival?: string;
    delayMinutes?: number;
    aircraft?: string;
    date: string;
  };
  showRisk?: boolean;
  onSelect?: () => void;
}) {
  const riskLevel =
    showRisk && flight.delayMinutes
      ? flight.delayMinutes > 30
        ? "High"
        : flight.delayMinutes > 15
          ? "Medium"
          : "Low"
      : "N/A";

  const riskClass =
    riskLevel === "High"
      ? "bg-red-500/20 text-red-400"
      : riskLevel === "Medium"
        ? "bg-yellow-500/20 text-yellow-400"
        : "bg-green-500/20 text-green-400";

  return (
    <article
      className="group bg-navy-950/50 backdrop-blur-sm border border-navy-800/50 rounded-2xl p-5 hover:bg-navy-900/80 transition-all duration-300 cursor-pointer"
      onClick={onSelect}
      aria-label={`Flight ${flight.flightNumber} information`}
      tabIndex={0}
      role="button"
    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex-1 min-w-0">
          <h3 className="text-base font-medium text-navy-100 group-hover:text-cyan-500 transition-colors mb-1 truncate">
            {flight.flightNumber}
          </h3>
          <p className="text-navy-400 text-sm">
            {flight.origin} → {flight.destination}
          </p>
        </div>

        <span
          className={`text-sm font-medium px-2.5 py-1 rounded shrink-0 ${riskClass}`}
        >
          {riskLevel}
        </span>
      </div>

      <div className="mt-3 flex flex-col sm:flex-row gap-4 pt-3 border-t border-navy-800/40">
        <div className="flex-1">
          <p className="text-navy-500 text-xs">Dep</p>
          <p className="text-navy-100 font-medium">
            {flight.scheduledDeparture}
          </p>
          {flight.actualDeparture && (
            <p className="text-navy-500 text-xs">Act: {flight.actualDeparture}</p>
          )}
        </div>
        <div className="flex-1">
          <p className="text-navy-500 text-xs">Arr</p>
          <p className="text-navy-100 font-medium">
            {flight.scheduledArrival || "—"}
          </p>
          {flight.actualArrival && (
            <p className="text-navy-500 text-xs">Act: {flight.actualArrival}</p>
          )}
        </div>
        {flight.aircraft && (
          <div className="flex-1">
            <p className="text-navy-500 text-xs">Aircraft</p>
            <p className="text-navy-100 font-medium">{flight.aircraft}</p>
          </div>
        )}
      </div>
    </article>
  );
}

/*
 * Status Badge - Flight / service status indicator
 * - Color-coded status display with complete literal Tailwind classes
 */
const STATUS_STYLES: Record<string, string> = {
  "On Time": "bg-green-500/20 text-green-400",
  Delayed: "bg-red-500/20 text-red-400",
  "At Risk": "bg-yellow-500/20 text-yellow-400",
  Cancelled: "bg-gray-500/20 text-gray-400",
  Diverted: "bg-purple-500/20 text-purple-400",
  scheduled: "bg-cyan-500/20 text-cyan-400",
  active: "bg-green-500/20 text-green-400",
  completed: "bg-gray-500/20 text-gray-400",
  delayed: "bg-red-500/20 text-red-400",
  cancelled: "bg-gray-500/20 text-gray-400",
  unknown: "bg-gray-500/20 text-gray-400",
  healthy: "bg-green-500/20 text-green-400",
  degraded: "bg-yellow-500/20 text-yellow-400",
  unavailable: "bg-red-500/20 text-red-400",
  Active: "bg-green-500/20 text-green-400",
  Available: "bg-cyan-500/20 text-cyan-400",
  Completed: "bg-gray-500/20 text-gray-400",
};

export function StatusBadge({
  status,
  size = "sm",
}: {
  status: string;
  size?: "sm" | "md";
}) {
  const styleClass = STATUS_STYLES[status] || "bg-navy-700/60 text-navy-300";

  const sizeClasses =
    size === "md"
      ? "px-3 py-1.5 text-sm rounded-lg"
      : "px-2 py-1 text-sm rounded";

  return (
    <span
      className={`inline-flex items-center ${sizeClasses} ${styleClass}`}
      data-status={status}
    >
      {status}
    </span>
  );
}

/*
 * Risk Gauge - Visual risk score display
 * - SVG ring with color-coded threshold
 * - Valid React style object + camelCase SVG attributes
 */
const RISK_RING: Record<string, { stroke: string; text: string }> = {
  high: { stroke: "stroke-red-500", text: "text-red-400" },
  medium: { stroke: "stroke-yellow-500", text: "text-yellow-400" },
  low: { stroke: "stroke-green-500", text: "text-green-400" },
};

export function RiskGauge({
  score,
  size = "md",
}: {
  score: number; // 0.0 to 1.0
  size?: "sm" | "md" | "lg";
}) {
  const level = score >= 0.7 ? "high" : score >= 0.4 ? "medium" : "low";
  const ring = RISK_RING[level];

  const box = size === "sm" ? 64 : size === "lg" ? 160 : 128;
  const strokeW = size === "sm" ? 5 : size === "lg" ? 9 : 7;
  const r = (box - strokeW) / 2;
  const circumference = 2 * Math.PI * r;
  const clamped = Math.max(0, Math.min(1, score));

  const dashStyle: CSSProperties = {
    strokeDasharray: `${circumference}`,
    strokeDashoffset: `${circumference * (1 - clamped)}`,
  };

  return (
    <div
      className={`relative shrink-0 ${size === "sm" ? "w-16 h-16" : size === "lg" ? "w-40 h-40" : "w-32 h-32"}`}
      role="img"
      aria-label={`Risk score ${Math.round(clamped * 100)} percent`}
    >
      <svg
        viewBox={`0 0 ${box} ${box}`}
        className="w-full h-full -rotate-90"
        aria-hidden="true"
      >
        <circle
          cx={box / 2}
          cy={box / 2}
          r={r}
          fill="none"
          stroke="var(--color-navy-800, #1e293b)"
          strokeWidth={strokeW}
        />
        <circle
          cx={box / 2}
          cy={box / 2}
          r={r}
          fill="none"
          className={ring.stroke}
          strokeWidth={strokeW}
          strokeLinecap="round"
          style={dashStyle}
        />
      </svg>
      <span
        className={`absolute inset-0 flex items-center justify-center text-sm font-semibold ${ring.text}`}
      >
        {Math.round(clamped * 100)}%
      </span>
    </div>
  );
}

/*
 * Loading Skeleton - Accessible loading state placeholder
 * - Used while data fetches from the backend
 * - Reduced-motion aware (global CSS disables the pulse)
 */
export function LoadingSkeleton({
  className = "",
  rows = 1,
}: {
  className?: string;
  rows?: number;
}) {
  return (
    <div
      className={`space-y-3 ${className}`}
      role="status"
      aria-label="Loading"
    >
      {Array.from({ length: Math.max(1, rows) }).map((_, i) => (
        <div
          key={i}
          className={`h-5 rounded bg-navy-900/80 animate-pulse ${
            i % 3 === 1 ? "w-3/4" : i % 3 === 2 ? "w-1/2" : "w-full"
          }`}
        />
      ))}
      <span className="sr-only">Loading…</span>
    </div>
  );
}

/*
 * Section Divider - Consistent section separation
 * - With optional label; accepts `className` for spacing
 */
export function SectionDivider({
  label,
  className = "",
  classNameExtra = "",
}: {
  label?: string;
  className?: string;
  classNameExtra?: string;
}) {
  if (label) {
    return (
      <div
        className={`flex items-center justify-center gap-4 mb-8 ${className} ${classNameExtra} relative z-10`}
      >
        <div className="flex-1 h-px bg-navy-800" />
        <span className="text-xs text-navy-500 uppercase tracking-widest px-2">
          {label}
        </span>
        <div className="flex-1 h-px bg-navy-800" />
      </div>
    );
  }

  return <hr className={`my-8 border-navy-800/50 ${className} ${classNameExtra}`} />;
}
